  addWire("Eldeco Fairway Reserve", "2024-03-11", "INFRASTRUCTURE", "CPR Cloverleaf Interchange & Dwarka Expressway Link Operational for New Gurgaon Sectors", "\u2022 Central Peripheral Road (CPR) cloverleaf interchange directly links New Gurgaon sectors to Dwarka Expressway and NH-48.\\n\u2022 Grade-separated multi-directional ramps eliminate traffic congestion at Kherki Daula.", "POSITIVE", "Pinnacle multi-highway transit integration for New Gurgaon residential hubs.", "The Hindu", "TH/NAT/67938445", "https://www.thehindu.com/news/national/pm-modi-opens-haryana-section-of-dwarka-expressway-lays-foundation-stone-for-114-nh-projects-worth-1-lakh-crore/article67938445.ece", false, 2);
