  addWire("Sobha Altus", "2025-10-06", "PRICING", "Sobha Limited Drives Robust NCR Sales Growth on Luxury Gurugram Portfolio", "\u2022 Sobha Limited recorded significant quarterly sales performance driven by strong demand for luxury residences in Gurugram.\\n\u2022 Premium developments across Sector 80, Sector 106, and Sector 63A contributed substantially to company-wide bookings.", "POSITIVE", "Strong operational sales cash flows fund on-time backward-integrated construction.", "Business Standard", "BS/MARKETS/125100600132", "https://www.business-standard.com/markets/news/sobha-shares-gain-4-percent-on-releasing-q2-update-check-all-details-here-125100600132_1.html", false, 3);
