  addWire("Godrej Sora", "2024-07-02", "PRICING", "Godrej Properties Clocks Record Launch Sales Exceeding \u20b93,000 Crore in Gurugram", "\u2022 Godrej Properties recorded landmark sales bookings of \u20b93,008 Crore at project launch in Gurugram, setting high benchmark in NCR.\\n\u2022 70% statutory escrow compliance established under Haryana RERA governance.", "POSITIVE", "Exceptional launch liquidity buffer provides self-funded construction security.", "Business Standard", "BS/MARKETS/124070200157", "https://www.business-standard.com/markets/capital-market-news/godrej-properties-bengaluru-based-residential-project-records-sales-of-over-rs-3-150-crore-124070200157_1.html", false, 3);
