  addWire("M3M Trump Towers - 1", "2023-11-03", "INFRASTRUCTURE", "\u20b9110 Crore Vatika Chowk Underpass Inaugurated; Signal-Free GCRE-to-SPR Transit Live", "\u2022 Haryana Chief Minister inaugurated the grade-separated underpass at Vatika Chowk, enabling signal-free vehicular transit between Golf Course Extension Road and Southern Peripheral Road (SPR).\\n\u2022 Eliminates major bottleneck, reducing commute times to Cyber City and NH-48 to 15 minutes.", "POSITIVE", "Major arterial bottleneck removed on prime luxury corridor.", "The Economic Times (ET Infra)", "ET/INFRA/104958117", "https://infra.economictimes.indiatimes.com/news/roads-highways/haryana-cm-inaugurates-underpass-at-vatika-chowk-in-gurugram/104958117", false, 2);
